/// Call from main() once, before reverseLookup is built.
void registerAdditionalConfigs(Map<String, List<dynamic>> target) {
  // Keep this file stable; only add new modules here.
  registerEcbuConfig(target);
  // registerMaintenanceConfig(target);
  // registerWhateverConfig(target);
}

/// We store match rules keyed by `msgType`.
/// The `List<int>` represents the byte-by-byte rule codes for
/// the data portion of your command.
///
/// For instance, if your "DO" (0x10) commands look like:
///   [ <CAN ID>, <srcID?>, <msgType=0x10>, <someByte>, <someByte>...]
/// Then you define a pattern for each position in that array.
final Map<int, List<int>> matchRulesByMsgType = {
  0x10: [
    0x00, // Byte1: ignore (example)
    0x01, // Byte2: must match exactly
    0x00, // Byte3: ignore
    0x00, // Byte4: ignore
    0x02, // Byte5: bit subset
    0x02, // Byte6: bit subset
    0x02, // Byte7: bit subset
    0x02, // Byte8: bit subset
    0x02, // Byte9: bit subset
    0x02, // Byte10: bit subset
    0x02, // Byte11: bit subset
    0x02, // Byte12: bit subset
    0x02, // Byte13: bit subset
    0x02, // Byte14: bit subset
    0x00, // Byte15: ignore
    0x00, // Byte16: ignore

    // ... etc. You can add as many as you like,
    // or fill with 0x00 to ignore extra positions.
  ],
  0x11: [
    0x00, // Byte1: ignore (example)
    0x01, // Byte2: must match exactly
    0x00, // Byte3: ignore
    0x00, // Byte4: ignore
    0x02, // Byte5: bit subset
    0x02, // Byte6: bit subset
    0x02, // Byte7: bit subset
    0x02, // Byte8: bit subset
    0x02, // Byte9: bit subset
    0x02, // Byte10: bit subset
    0x02, // Byte11: bit subset
    0x02, // Byte12: bit subset
    0x02, // Byte13: bit subset
    0x02, // Byte14: bit subset
    0x00, // Byte15: ignore
    0x00, // Byte16: ignore
  ],
  0x13: [
    0x00, // Byte1: ignore (example)
    0x01, // Byte2: must match exactly
    0x00, // Byte3: ignore
    0x00, // Byte4: ignore
    0x02, // Byte5: bit subset
    0x02, // Byte6: bit subset
    0x00, // Byte7: ignore
    0x01, // Byte8: exact match
  ],
  0x14: [
    0x00, // Byte1: ignore (example)
    0x01, // Byte2: must match exactly
    0x00, // Byte3: ignore
    0x00, // Byte4: ignore
